package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.JwksUriVO;

class JwksUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of jwks uri of oauth client")
  void test_jwks_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    JwksUriValueHolder<Object> value = new JwksUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.jwksUri("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getJwksUriValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getJwksUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.jwksUriNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getJwksUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getJwksUri().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of jwks uri of oauth client")
  void test_jwks_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    JwksUriValueHolder<Object> value = new JwksUriValueHolder<>(holder);
    JwksUriVO vo = JwksUriVO.from("one");
    Assertions.assertFalse(value.getJwksUriValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.jwksUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getJwksUriValue().orElseThrow());
    Assertions.assertSame(holder, value.jwksUri(Optional.empty()));
    Assertions.assertFalse(value.getJwksUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.jwksUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getJwksUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of jwks uri of oauth client against the original")
  void test_jwks_uri_value_holder_read() {
    Object holder = new Object();
    JwksUriValueHolder<Object> value = new JwksUriValueHolder<>(holder);
    JwksUriVO vo = JwksUriVO.from("one");
    JwksUriVO other = JwksUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getJwksUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readJwksUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readJwksUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.jwksUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readJwksUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readJwksUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of jwks uri of oauth client")
  void test_jwks_uri_value_holder_unset() {
    Object holder = new Object();
    JwksUriValueHolder<Object> value = new JwksUriValueHolder<>(holder);
    JwksUriVO vo = JwksUriVO.from("one");
    value.jwksUri(vo);
    Assertions.assertSame(holder, value.unsetJwksUriIfMatches("jwksUri_other"));
    Assertions.assertTrue(value.getJwksUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetJwksUriIfMatches("jwksUri"));
    Assertions.assertFalse(value.getJwksUriValue().isPresent(),
        "The field name must clear the value");
    value.jwksUri(vo);
    Assertions.assertSame(holder, value.unsetJwksUri());
    Assertions.assertFalse(value.getJwksUriValue().isPresent(), "Unset must clear the value");
  }
}
